/**
 * Shell URL segment — `scyk` (SC Y khoa). Must match `mfe.routes.json` → `routes[0]`.
 * Package import map: `@linm/inc`.
 *
 * Browser URL: `appPath(scykRoutes.reportServiceMismatch)` → `/scyk/bc/nham-dv`
 */
import { normalizeMenuPathToRoute, SCYK_DEFAULT_ROUTE, scykRoutes } from './scykRoutes';

export const APP_UI_PREFIX = 'scyk';

export { scykRoutes, SCYK_DEFAULT_ROUTE, normalizeMenuPathToRoute };

const SHELL_PUBLIC_PATHS = new Set([
  '/login',
  '/logout',
  '/unauthorized',
  '/session-expired',
  '/oidc-callback',
  '/oidc-silent-renew',
]);

const SCYK_FIRST_SEGMENTS = new Set(['su-co', 'bc', 'canh-bao', 'dev']);

/** Browser URL: `/scyk/...` */
export function appPath(path = ''): string {
  const trimmed = path.replace(/^\/+/, '');
  if (!trimmed) return `/${APP_UI_PREFIX}`;
  if (trimmed === APP_UI_PREFIX || trimmed.startsWith(`${APP_UI_PREFIX}/`)) {
    return `/${trimmed}`;
  }
  return `/${APP_UI_PREFIX}/${trimmed}`;
}

export function stripAppPrefix(pathname: string): string {
  const base = pathname.replace(/\/+$/, '') || '/';
  const prefix = `/${APP_UI_PREFIX}`;
  if (base === prefix) return '/';
  if (base.startsWith(`${prefix}/`)) return base.slice(prefix.length) || '/';
  return base;
}

function normalizePathname(pathname: string): string {
  if (!pathname || pathname === '/') return '/';
  return pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
}

export function isDomainBrowserPath(pathname: string): boolean {
  const path = stripAppPrefix(normalizePathname(pathname));
  if (path === '/') return false;
  const first = path.split('/').filter(Boolean)[0];
  return !!first && SCYK_FIRST_SEGMENTS.has(first);
}

export function ensureAppPrefixedPath(pathname: string): string {
  const base = normalizePathname(pathname);
  if (SHELL_PUBLIC_PATHS.has(base)) return base;
  if (base === '/m-inc' || base.startsWith('/m-inc/')) {
    return appPath(base.replace(/^\/m-inc\/?/, ''));
  }
  const prefix = `/${APP_UI_PREFIX}`;
  if (base === prefix || base.startsWith(`${prefix}/`)) return base;
  if (!isDomainBrowserPath(base)) return base;
  const relative = base.replace(/^\//, '');
  if (relative.startsWith('medical-incidents') || relative.startsWith('fall-location-warnings')) {
    return appPath(normalizeMenuPathToRoute(relative));
  }
  return appPath(relative);
}
