// ─── helpers ────────────────────────────────────────────────────────────────

const fmtDate = (iso: string | null | undefined) => {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

const fmtTime = (iso: string | null | undefined) => {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
};

const CB = ({ checked, label }: { checked: boolean; label: string }) => (
  <span className={styles.checkItem}>
    <span className={checked ? styles.checked : styles.unchecked} />
    {' '}{label}
  </span>
);

/** Render only checked items; if none checked renders a dash */
const CheckedList = ({ items }: { items: Array<{ checked: boolean; label: string }> }) => {
  const hit = items.filter((x) => x.checked);
  if (hit.length === 0) return <span style={{ color: '#888', fontStyle: 'italic' }}>—</span>;
  return <>{hit.map((x, idx) => <div key={idx}><CB checked label={x.label} /></div>)}</>;
};

/** Pick the single selected option from a radio group */
const RadioSelected = ({ value, options }: { value: string | null | undefined; options: Array<{ value: string; label: string }> }) => {
  const found = options.find((o) => o.value === value);
  return found ? <CB checked label={found.label} /> : <span style={{ color: '#888', fontStyle: 'italic' }}>—</span>;
};

