// ─── Export ──────────────────────────────────────────────────────────────────

export interface PrintSelection {
  baoCao:    boolean;  // Báo cáo sự cố y khoa
  phanTich:  boolean;  // Tìm hiểu và phân tích
  bienBan:   boolean;  // Biên bản đánh giá
}

interface PrintableIncidentDocsProps {
  incident:  MedicalIncident;
  selection: PrintSelection;
}

export const PrintableIncidentDocs = React.forwardRef<HTMLDivElement, PrintableIncidentDocsProps>(
  ({ incident, selection }, ref) => (
    <div ref={ref} className={styles.printRoot}>
      {selection.baoCao   && <BaoCaoSuCo   incident={incident} />}
      {selection.phanTich && <TimHieuPhanTich incident={incident} />}
      {selection.bienBan  && <BienBanDanhGia  incident={incident} />}
    </div>
  ),
);

PrintableIncidentDocs.displayName = 'PrintableIncidentDocs';
