/**
 * DateRangeFilter — common date filter component
 *
 * Renders a styled <select> for preset selection.
 * When "Tháng" or "Năm" is selected a MonthYearPill appears next to the
 * select so the user can pick the specific month/year inline.
 * When "Chọn ngày" is selected, from/to date inputs appear.
 *
 * Preset constants (export for consumers):
 *   DEFAULT_LIST_PRESETS  — '', today, this-week, this-month, custom
 *   REPORT_PRESETS        — '', today, this-week, month, year, custom
 */
import React, { useEffect, useState } from 'react';
import { Input } from '../Input';
import { MonthYearPill } from './MonthYearPill';
import styles from './DateRangeFilter.module.css';

export type DatePreset = 'today' | 'this-week' | 'this-month' | 'month' | 'year' | 'custom' | '';

export interface DateRangeValue {
  fromDate?: string;
  toDate?:   string;
}

interface Props {
  fromDate?: string;
  toDate?:   string;
  onChange:  (value: DateRangeValue) => void;
  presets?:  DatePreset[];
}

// ── Helpers ────────────────────────────────────────────────────

function toISODate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function getPresetRange(preset: DatePreset, refMonth?: string, refYear?: number): DateRangeValue {
  const today = new Date();
  if (preset === 'today') {
    const s = toISODate(today);
    return { fromDate: s, toDate: s };
  }
  if (preset === 'this-week') {
    const day = today.getDay() === 0 ? 6 : today.getDay() - 1;
    const mon = new Date(today); mon.setDate(today.getDate() - day);
    const sun = new Date(mon);   sun.setDate(mon.getDate() + 6);
    return { fromDate: toISODate(mon), toDate: toISODate(sun) };
  }
  if (preset === 'this-month') {
    const first = new Date(today.getFullYear(), today.getMonth(), 1);
    const last  = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    return { fromDate: toISODate(first), toDate: toISODate(last) };
  }
  if (preset === 'month' && refMonth) {
    const [y, m] = refMonth.split('-').map(Number);
    return { fromDate: toISODate(new Date(y, m - 1, 1)), toDate: toISODate(new Date(y, m, 0)) };
  }
  if (preset === 'year') {
    const y = refYear ?? today.getFullYear();
    return { fromDate: `${y}-01-01`, toDate: `${y}-12-31` };
  }
  return {};
}

function detectPreset(fromDate?: string, toDate?: string, availablePresets?: DatePreset[]): DatePreset {
  const has = (p: DatePreset) => !availablePresets || availablePresets.includes(p);

  if (!fromDate && !toDate) return has('') ? '' : (availablePresets?.[0] ?? '');

  const today = toISODate(new Date());
  if (has('today') && fromDate === today && toDate === today) return 'today';

  if (has('this-week')) {
    const tw = getPresetRange('this-week');
    if (fromDate === tw.fromDate && toDate === tw.toDate) return 'this-week';
  }

  if (fromDate && toDate) {
    // Check month/year BEFORE this-month so current-month picked as 'month' preset isn't misidentified
    if (has('month')) {
      const [fy, fm] = fromDate.split('-').map(Number);
      const expectedLast = toISODate(new Date(fy, fm, 0));
      if (fromDate === `${fy}-${String(fm).padStart(2, '0')}-01` && toDate === expectedLast) return 'month';
    }
    if (has('year')) {
      const fy = fromDate.slice(0, 4);
      if (fromDate === `${fy}-01-01` && toDate === `${fy}-12-31`) return 'year';
    }
    if (has('this-month')) {
      const tm = getPresetRange('this-month');
      if (fromDate === tm.fromDate && toDate === tm.toDate) return 'this-month';
    }
  }

  return has('custom') ? 'custom' : (availablePresets?.[0] ?? '');
}

const currentYear  = new Date().getFullYear();
const currentMonth = `${currentYear}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

export const DEFAULT_LIST_PRESETS: DatePreset[] = ['', 'today', 'this-week', 'this-month', 'custom'];
export const REPORT_PRESETS:       DatePreset[] = ['', 'today', 'this-week', 'month', 'year', 'custom'];

/** Static option labels */
function getOptionLabel(p: DatePreset): string {
  const MAP: Record<string, string> = {
    '':           'Tất cả ngày',
    'today':      'Hôm nay',
    'this-week':  'Tuần này',
    'this-month': 'Tháng này',
    'month':      'Tháng',
    'year':       'Năm',
    'custom':     'Chọn ngày…',
  };
  return MAP[p] ?? p;
}

// ── Component ────────────────────────────────────────────────────

export const DateRangeFilter: React.FC<Props> = ({
  fromDate,
  toDate,
  onChange,
  presets = DEFAULT_LIST_PRESETS,
}) => {
  const [activePreset,   setActivePreset]   = useState<DatePreset>(() => detectPreset(fromDate, toDate, presets));
  const [selectedMonth,  setSelectedMonth]  = useState<string>(() => fromDate?.slice(0, 7) ?? currentMonth);
  const [selectedYear,   setSelectedYear]   = useState<string>(() => fromDate?.slice(0, 4) ?? String(currentYear));

  useEffect(() => {
    const detected = detectPreset(fromDate, toDate, presets);
    setActivePreset(detected);
    if (detected === 'month' && fromDate) setSelectedMonth(fromDate.slice(0, 7));
    if (detected === 'year'  && fromDate) setSelectedYear(fromDate.slice(0, 4));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fromDate, toDate]);

  const handleSelectChange = (preset: DatePreset) => {
    setActivePreset(preset);
    if (preset === '')                onChange({ fromDate: undefined, toDate: undefined });
    else if (preset === 'today')      onChange(getPresetRange('today'));
    else if (preset === 'this-week')  onChange(getPresetRange('this-week'));
    else if (preset === 'this-month') onChange(getPresetRange('this-month'));
    else if (preset === 'month')      onChange(getPresetRange('month', selectedMonth));
    else if (preset === 'year')       onChange(getPresetRange('year', undefined, Number(selectedYear)));
    // 'custom': just show the date pickers, don't fire onChange yet
  };

  const handleMonthChange = (val: string) => {
    if (!val) return;
    setSelectedMonth(val);
    onChange(getPresetRange('month', val));
  };

  const handleYearChange = (val: string) => {
    const y = Number(val);
    if (!y || y < 2000 || y > currentYear + 1) return;
    setSelectedYear(val);
    onChange(getPresetRange('year', undefined, y));
  };

  const handleFrom = (e: React.ChangeEvent<HTMLInputElement>) => {
    setActivePreset('custom');
    onChange({ fromDate: e.target.value || undefined, toDate });
  };

  const handleTo = (e: React.ChangeEvent<HTMLInputElement>) => {
    setActivePreset('custom');
    onChange({ fromDate, toDate: e.target.value || undefined });
  };

  return (
    <div className={styles.wrapper}>
      {/* Preset select */}
      <select
        className={styles.select}
        value={activePreset}
        onChange={(e) => handleSelectChange(e.target.value as DatePreset)}
        aria-label="Lọc theo ngày"
      >
        {presets.map((p) => (
          <option key={p} value={p}>
            {getOptionLabel(p)}
          </option>
        ))}
      </select>

      {/* Month picker — shown when 'month' is active */}
      {activePreset === 'month' && (
        <MonthYearPill
          type="month"
          active
          value={selectedMonth}
          max={currentMonth}
          onChange={handleMonthChange}
          onActivate={() => {}}
        />
      )}

      {/* Year picker — shown when 'year' is active */}
      {activePreset === 'year' && (
        <MonthYearPill
          type="year"
          active
          value={selectedYear}
          onChange={handleYearChange}
          onActivate={() => {}}
        />
      )}

      {/* Custom from–to date pickers */}
      {activePreset === 'custom' && (
        <div className={styles.customPickers}>
          <Input
            type="date"
            size="small"
            value={fromDate ?? ''}
            onChange={handleFrom}
            placeholder="Từ ngày"
            aria-label="Từ ngày"
          />
          <span className={styles.sep}>→</span>
          <Input
            type="date"
            size="small"
            value={toDate ?? ''}
            onChange={handleTo}
            placeholder="Đến ngày"
            aria-label="Đến ngày"
          />
        </div>
      )}
    </div>
  );
};
