import React, { Suspense, useEffect } from 'react';

import { Routes, Route, Navigate } from 'react-router-dom';

import { NotFoundPage } from '@linm-soft/common-components';

import { showDevNav, isStandalone } from './dev/isStandalone';

import { devModules } from './dev/devRoutes';

import { ToastProvider, ReduxToastContainer } from './components/common/Toast';

import { AlertProvider } from './components/common/Alert';

import { ProtectedRoute } from './components/auth/ProtectedRoute';

import { DomainShell } from './components/layout/AppLayout';

import { useDomainRealtime } from './hooks/useDomainRealtime';

import UnauthorizedPage from './pages/UnauthorizedPage';

import MedicalIncidentsListPage from './pages/MedicalIncidentsListPage';

import MedicalIncidentFormPage from './pages/MedicalIncidentFormPage';

import MedicalIncidentReportPage from './pages/MedicalIncidentReportPage';

import FallLocationWarningListPage from './pages/FallLocationWarningListPage';

import FallLocationWarningFormPage from './pages/FallLocationWarningFormPage';

import ServiceMismatchReportPage from './pages/ServiceMismatchReportPage';

import FallIncidentReportPage from './pages/FallIncidentReportPage';

import DailyIncidentReportsListPage from './pages/DailyIncidentReportsListPage';

import DailyIncidentReportFormPage from './pages/DailyIncidentReportFormPage';

import { APP_UI_PREFIX, appPath, SCYK_DEFAULT_ROUTE } from './config/appRoutes';

import { scykRoutes } from './config/scykRoutes';

import { registerRefreshSuccessCallback } from './services/api';

import { updateUserFromRefresh } from './store/slices/authSlice';

import { mapAuthUser } from './services/auth/mapper';

import { store } from './store/store';



const DevPage = React.lazy(() =>

  import('./dev/DevPage').then((m) => ({ default: m.DevPage })),

);



/** @linm/inc — SCYK (`/scyk/su-co`, `/scyk/bc/nham-dv`, …). */

const App: React.FC = () => {

  useDomainRealtime();



  useEffect(() => {

    registerRefreshSuccessCallback((raw) => {

      if (raw.user) {

        const updatedUser = mapAuthUser(raw.user as Parameters<typeof mapAuthUser>[0]);

        store.dispatch(updateUserFromRefresh(updatedUser));

      }

    });

  }, []);



  return (

    <AlertProvider>

      <ToastProvider>

        <ReduxToastContainer />

        <Routes>

          {showDevNav && (

            <Route

              path="/dev"

              element={

                <Suspense fallback={null}>

                  <DevPage modules={devModules} />

                </Suspense>

              }

            />

          )}

          {isStandalone && (

            <Route path="/unauthorized" element={<UnauthorizedPage />} />

          )}

          <Route path="/" element={<Navigate to={appPath(SCYK_DEFAULT_ROUTE)} replace />} />

          <Route

            path={`/${APP_UI_PREFIX}`}

            element={

              <ProtectedRoute>

                <DomainShell />

              </ProtectedRoute>

            }

          >

            <Route index element={<Navigate to={SCYK_DEFAULT_ROUTE} replace />} />

            <Route path={scykRoutes.reportServiceMismatch} element={<ServiceMismatchReportPage />} />

            <Route path={scykRoutes.reportFall} element={<FallIncidentReportPage />} />

            <Route path={scykRoutes.reportStats} element={<MedicalIncidentReportPage />} />

            <Route path={scykRoutes.reportDailyNew} element={<DailyIncidentReportFormPage />} />

            <Route path={scykRoutes.reportDaily} element={<DailyIncidentReportsListPage />} />

            <Route path={scykRoutes.fallWarningNew} element={<FallLocationWarningFormPage />} />

            <Route path={`${scykRoutes.fallWarnings}/:id`} element={<FallLocationWarningFormPage />} />

            <Route path={scykRoutes.fallWarnings} element={<FallLocationWarningListPage />} />

            <Route path={scykRoutes.incidentNew} element={<MedicalIncidentFormPage />} />

            <Route path={`${scykRoutes.home}/:id`} element={<MedicalIncidentFormPage />} />

            <Route path={scykRoutes.home} element={<MedicalIncidentsListPage />} />

            <Route path="*" element={<NotFoundPage />} />

          </Route>

          <Route path="*" element={<NotFoundPage />} />

        </Routes>

      </ToastProvider>

    </AlertProvider>

  );

};



export default App;

