/**
 * Redux slice for the Messages Inbox (separate from the notification bell).
 *
 * State shape:
 *  - conversations:     list of conversation summaries (paged)
 *  - totalCount:        total server-side count
 *  - loading:           initial fetch in progress
 *  - hasMore:           more pages available
 *  - page:              current page
 *  - selectedEntityId:  entity currently open in ChatPanel (null = nothing selected)
 *  - selectedEntityType
 *  - unreadMessageCount: badge count for "Tin nhắn" nav item
 *                        incremented by NEW_MESSAGE SignalR events,
 *                        reset when user visits /messages
 */
import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { apiClient } from '../../services/api';
import { BffResponse, unwrap } from '../../services/shared/bffEnvelope';
import { conversationEndpoint } from '../../services/message/conversationEndpoint';
import type { ConversationSummary, ConversationLastMessage } from '../../services/message/conversationTypes';

interface MessagesInboxState {
  conversations:       ConversationSummary[];
  totalCount:          number;
  loading:             boolean;
  loadingMore:         boolean;
  hasMore:             boolean;
  page:                number;
  selectedEntityId:    string | null;
  selectedEntityType:  'ticket' | 'task' | 'incident' | null;
  unreadMessageCount:  number;
}

const initialState: MessagesInboxState = {
  conversations:      [],
  totalCount:         0,
  loading:            false,
  loadingMore:        false,
  hasMore:            true,
  page:               1,
  selectedEntityId:   null,
  selectedEntityType: null,
  unreadMessageCount: 0,
};

// ── Async thunks ──────────────────────────────────────────────────────────────

/** Fetch first page of conversations (replaces list). */
export const fetchConversations = createAsyncThunk(
  'messagesInbox/fetchConversations',
  async (entityType?: 'ticket' | 'task' | 'incident') => {
    return await conversationEndpoint.getConversations(1, 20, entityType);
  },
);

/** Load next page (append). */
export const fetchMoreConversations = createAsyncThunk(
  'messagesInbox/fetchMoreConversations',
  async ({ page, entityType }: { page: number; entityType?: 'ticket' | 'task' | 'incident' }) => {
    return await conversationEndpoint.getConversations(page, 20, entityType);
  },
);

/** Fetch the server-side unread NEW_MESSAGE count (called on app startup / reconnect). */
export const fetchUnreadMessageCount = createAsyncThunk(
  'messagesInbox/fetchUnreadMessageCount',
  async () => {
    const res = await apiClient.get<BffResponse<{ count: number }>>('/messages/unread-count');
    return unwrap(res).count;
  },
);

// ── Slice ─────────────────────────────────────────────────────────────────────

/**
 * Recomputes unreadMessageCount as the sum of all per-conversation unreadCounts.
 * Call this after any mutation that changes a conversation's unreadCount.
 * For convs not yet in the list, the fallback +1 in updateConversationFromMessage handles the gap.
 */
function recalcUnreadTotal(state: MessagesInboxState) {
  state.unreadMessageCount = state.conversations.reduce(
    (sum, c) => sum + (c.unreadCount ?? 0), 0
  );
}

const messagesInboxSlice = createSlice({
  name: 'messagesInbox',
  initialState,
  reducers: {
    /** Select a conversation to view in the ChatPanel. */
    selectConversation(
      state,
      action: PayloadAction<{ entityId: string; entityType: 'ticket' | 'task' | 'incident' }>,
    ) {
      state.selectedEntityId   = action.payload.entityId;
      state.selectedEntityType = action.payload.entityType;
    },

    /** Clear selected conversation (e.g. when user leaves MessagesPage). */
    clearSelectedConversation(state) {
      state.selectedEntityId   = null;
      state.selectedEntityType = null;
    },

    /**
     * Called when a NEW_MESSAGE SignalR event arrives.
     * Updates the conversation's lastMessage + bubbles it to top of list.
     * If the conversation is not yet in the list (first message ever), a partial
     * entry is added — a reload will populate full details.
     */
    updateConversationFromMessage(
      state,
      action: PayloadAction<{
        entityId:   string;
        entityType: 'ticket' | 'task' | 'incident';
        lastMessage: ConversationLastMessage;
      }>,
    ) {
      const { entityId, entityType, lastMessage } = action.payload;
      const idx = state.conversations.findIndex(
        (c) => c.entityId === entityId && c.entityType === entityType,
      );
      if (idx !== -1) {
        const updated = {
          ...state.conversations[idx],
          lastMessage,
          totalMessageCount: state.conversations[idx].totalMessageCount + 1,
          unreadCount:       (state.conversations[idx].unreadCount ?? 0) + 1,
        };
        // Move to top
        state.conversations.splice(idx, 1);
        state.conversations.unshift(updated);
        // Derive total from per-conv sum
        recalcUnreadTotal(state);
      } else {
        // Conv not in list yet → fallback increment so badge stays accurate
        state.unreadMessageCount += 1;
      }
    },

    /**
     * Called from useConversations (NewMessage room event).
     * Updates lastMessage preview + totalCount only — does NOT touch unreadCount
     * (unreadCount is already incremented by updateConversationFromMessage via AppLayout).
     */
    updateConversationPreview(
      state,
      action: PayloadAction<{
        entityId:   string;
        entityType: 'ticket' | 'task' | 'incident';
        lastMessage: ConversationLastMessage;
      }>,
    ) {
      const { entityId, entityType, lastMessage } = action.payload;
      const idx = state.conversations.findIndex(
        (c) => c.entityId === entityId && c.entityType === entityType,
      );
      if (idx !== -1) {
        const updated = {
          ...state.conversations[idx],
          lastMessage,
          totalMessageCount: state.conversations[idx].totalMessageCount + 1,
          // unreadCount intentionally NOT changed here
        };
        state.conversations.splice(idx, 1);
        state.conversations.unshift(updated);
      }
    },

    /** Increment unread badge (from NEW_MESSAGE SignalR when user is NOT on /messages). */
    incrementUnreadMessages(state) {
      state.unreadMessageCount += 1;
    },

    /** Reset unread badge + all per-conversation unread counts (when user opens /messages). */
    clearUnreadMessages(state) {
      state.conversations.forEach((c) => { c.unreadCount = 0; });
      state.unreadMessageCount = 0;
    },

    /** Clear unreadCount on a specific conversation (when user opens it) and sync the total badge. */
    markConversationReadLocal(state, action: PayloadAction<string>) {
      const conv = state.conversations.find((c) => c.entityId === action.payload);
      if (conv) {
        conv.unreadCount = 0;
        recalcUnreadTotal(state);
      }
    },

    /** Clear all state on logout. */
    clearMessagesInbox(state) {
      Object.assign(state, initialState);
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchConversations.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchConversations.fulfilled, (state, action) => {
        state.loading       = false;
        state.conversations = action.payload.items;
        state.totalCount    = action.payload.totalCount;
        state.page          = 1;
        state.hasMore       = action.payload.items.length < action.payload.totalCount;
        // Sync total badge from fresh server data
        recalcUnreadTotal(state);
      })
      .addCase(fetchConversations.rejected, (state) => {
        state.loading = false;
      });

    builder
      .addCase(fetchMoreConversations.pending, (state) => {
        state.loadingMore = true;
      })
      .addCase(fetchMoreConversations.fulfilled, (state, action) => {
        state.loadingMore   = false;
        state.conversations = [...state.conversations, ...action.payload.items];
        state.page          = action.payload.page;
        state.hasMore       = state.conversations.length < action.payload.totalCount;
        recalcUnreadTotal(state);
      })
      .addCase(fetchMoreConversations.rejected, (state) => {
        state.loadingMore = false;
      });

    // Sync badge from server on startup / reconnect
    builder.addCase(fetchUnreadMessageCount.fulfilled, (state, action) => {
      state.unreadMessageCount = action.payload;
    });
  },
});

export const {
  selectConversation,
  clearSelectedConversation,
  updateConversationFromMessage,
  updateConversationPreview,
  incrementUnreadMessages,
  clearUnreadMessages,
  markConversationReadLocal,
  clearMessagesInbox,
} = messagesInboxSlice.actions;

export default messagesInboxSlice.reducer;
