/**
 * Auth navigation menu SSOT — paths `/scyk/...` (segment tiếng Việt, `scykRoutes`).
 */
import type { NavSection } from '@linm-soft/common-components';
import { appPath } from '../config/appRoutes';
import { scykRoutes } from '../config/scykRoutes';

export const NAV_AUTH_APP_ID = 'medical-incidents' as const;

export interface AuthNavMenuLeaf {
  id: string;
  label: string;
  icon: string;
  path: string;
}

export const SCYK_MENU_LEAVES: AuthNavMenuLeaf[] = [
  {
    id: 'medical-incidents',
    label: 'Danh Sách Sự Cố',
    icon: 'fas fa-list-alt',
    path: appPath(scykRoutes.home),
  },
  {
    id: 'fall-location-warnings',
    label: 'Cảnh Báo Té Ngã',
    icon: 'fas fa-map-marker-alt',
    path: appPath(scykRoutes.fallWarnings),
  },
  {
    id: 'medical-incidents-daily-reports',
    label: 'Báo Cáo Hằng Ngày',
    icon: 'fas fa-calendar-check',
    path: appPath(scykRoutes.reportDaily),
  },
  {
    id: 'medical-incidents-reports',
    label: 'Báo Cáo Thống Kê',
    icon: 'fas fa-chart-bar',
    path: appPath(scykRoutes.reportStats),
  },
  {
    id: 'medical-incidents-reports-service-mismatch',
    label: 'Báo Cáo Nhầm Dịch Vụ',
    icon: 'fas fa-exchange-alt',
    path: appPath(scykRoutes.reportServiceMismatch),
  },
  {
    id: 'medical-incidents-reports-fall',
    label: 'Báo Cáo Sự Cố Té Ngã',
    icon: 'fas fa-walking',
    path: appPath(scykRoutes.reportFall),
  },
];

export function buildAuthNavSections(): Array<{
  title: string;
  items: AuthNavMenuLeaf[];
}> {
  return [
    { title: 'Sự Cố Y Khoa', items: SCYK_MENU_LEAVES.slice(0, 2) },
    { title: 'Báo Cáo', items: SCYK_MENU_LEAVES.slice(2) },
  ];
}

export function listAuthMenuPaths(): string[] {
  return SCYK_MENU_LEAVES.map((l) => l.path);
}

export function toNavSections(
  sections: Array<{ title: string; items: AuthNavMenuLeaf[] }>,
): NavSection[] {
  return sections.map((section) => ({
    title: section.title,
    items: section.items.map((item) => ({
      id: item.id,
      label: item.label,
      icon: item.icon,
      path: item.path,
    })),
  }));
}
