function renderNotify(val: unknown, opts: FullMapRowOptions): React.ReactNode {
  const v = String(val ?? '');
  const label = opts.notifyStatusOptions?.find((o) => String(o.value) === v)?.label
    ?? (v === 'yes' ? 'Có' : v === 'no' ? 'Không' : v === 'not_recorded' ? 'Không ghi' : '');
  return label || '—';
}

const PREVIEW_PAGE_SIZE = 5;

const Step2MapPreview: React.FC<Step2Props> = ({
  file, template, rows, departmentOptions, formOptions, onResolve, onResolveAll, onBack, onNext,
}) => {
  const [page, setPage] = useState(0);
  const [bulkConfirm, setBulkConfirm] = useState<BulkConfirm | null>(null);
  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set());
  const [showOnlyErrors, setShowOnlyErrors] = useState(false);

  const unresolvedCount = countUnresolved(rows);
  const filteredRows = showOnlyErrors ? rows.filter((r) => Object.keys(r.unresolved).length > 0) : rows;
  const totalPages = Math.ceil(filteredRows.length / PREVIEW_PAGE_SIZE);
  const visibleRows = filteredRows.slice(page * PREVIEW_PAGE_SIZE, (page + 1) * PREVIEW_PAGE_SIZE);

  const templateLabel =
    template === 'danhsach' ? '📋 Danh sách sự cố' :
    template === 'phantich' ? '🔬 Phân tích sự cố' :
    '❓ Không xác định mẫu';

  const countSameRaw = (field: string, rawText: string): number =>
    rows.filter((r) => r.unresolved[field] && getRawDeptText(r, field) === rawText).length;

  const handleDeptChange = (row: ImportRow, field: string, val: string) => {
    if (!val) return;
    const opt     = departmentOptions.find((o) => String(o.value) === val);
    const label   = opt?.label ?? '';
    // Always apply to current row immediately so the select sticks
    onResolve(row.rowIndex, field, val, label);
    // Check for OTHER rows with same raw text and offer bulk apply
    const rawText  = getRawDeptText(row, field);
    const otherAffected = countSameRaw(field, rawText) - 1; // subtract current row
    if (otherAffected > 0) {
      setBulkConfirm({ field, rawText, value: val, label, affectedCount: otherAffected });
    }
  };

  const handleBulkConfirmYes = () => {
    if (!bulkConfirm) return;
    onResolveAll(bulkConfirm.rawText, bulkConfirm.field, bulkConfirm.value, bulkConfirm.label);
    setBulkConfirm(null);
  };

  const handleBulkConfirmNo = () => {
    // Current row was already resolved immediately; just dismiss the dialog
    setBulkConfirm(null);
  };

  const toggleExpand = (idx: number) =>
    setExpandedRows((prev) => {
      const next = new Set(prev);
      next.has(idx) ? next.delete(idx) : next.add(idx);
      return next;
    });

  const allDeptOptions: SelectOption[] = departmentOptions;
  const fullOpts = formOptions as FullMapRowOptions;

  return (
    <div className={styles.step2}>
      {/* Summary bar */}
      <div className={styles.summaryBar}>
        <span className={styles.summaryItem}><strong>{rows.length}</strong> hàng dữ liệu</span>
        <span className={styles.summaryItem}>Mẫu: <strong>{templateLabel}</strong></span>
        <span className={styles.summaryItem}>File: <strong>{file.name}</strong></span>
        {unresolvedCount > 0 && (
          <span className={`${styles.summaryItem} ${styles.summaryWarning}`}>
            ⚠️ <strong>{unresolvedCount}</strong> hàng cần xử lý khoa/phòng
          </span>
        )}
        <label className={styles.errorFilterToggle}>
          <input
            type="checkbox"
            checked={showOnlyErrors}
            onChange={(e) => { setShowOnlyErrors(e.target.checked); setPage(0); }}
          />
          <span>Chỉ hiện hàng lỗi {unresolvedCount > 0 ? `(${unresolvedCount})` : ''}</span>
        </label>
      </div>

      {/* Row cards */}
      <div className={styles.rowCards}>
        {visibleRows.map((row) => {
          const hasUnresolved = Object.keys(row.unresolved).length > 0;
          const isExpanded    = expandedRows.has(row.rowIndex);
          const visibleDefs   = isExpanded ? FIELD_DEFS : FIELD_DEFS.slice(0, 6);

          return (
            <div key={row.rowIndex} className={`${styles.rowCard} ${hasUnresolved ? styles.rowCardUnresolved : ''}`}>
              {/* Card header */}
              <div className={styles.rowCardHeader}>
                <span className={styles.rowCardNum}>#{row.rowIndex + 1}</span>
                <span className={styles.rowCardTitle}>
                  {String(row.mapped.patientName || '(Không có tên)')}
                  {row.mapped.patientCode ? <span className={styles.rowCardCode}> · {row.mapped.patientCode}</span> : null}
                </span>
                {hasUnresolved && <span className={styles.rowCardBadge}>⚠️ Cần xử lý</span>}
                {row.warnings.length > 0 && <span className={styles.rowCardWarn}>⚠️ {row.warnings.length} cảnh báo</span>}
                <button className={styles.expandBtn} onClick={() => toggleExpand(row.rowIndex)}>
                  {isExpanded ? '▲ Thu gọn' : '▼ Xem tất cả fields'}
                </button>
              </div>

              {/* Field grid */}
              <div className={styles.fieldGrid}>
                {visibleDefs.map((def) => {
                  const rawVal = (row.mapped as Record<string, unknown>)[def.key];
                  const rendered = def.render
                    ? def.render(row, fullOpts, allDeptOptions, handleDeptChange)
                    : (rawVal != null && rawVal !== '' ? String(rawVal) : '—');
                  return (
                    <div key={def.key} className={styles.fieldItem}>
                      <span className={styles.fieldLabel}>{def.label}</span>
                      <span className={styles.fieldValue}>{rendered}</span>
                    </div>
                  );
                })}
              </div>

              {/* Staff analysis summary if phantich */}
              {isExpanded && row.mapped.staffAnalysis && (
                <div className={styles.saSection}>
                  <div className={styles.saSectionTitle}>📋 Phân tích sự cố (Tab 4A)</div>
                  <div className={styles.fieldGrid}>
                    <div className={styles.fieldItem}>
                      <span className={styles.fieldLabel}>Mô tả chi tiết</span>
                      <span className={`${styles.fieldValue} ${styles.descText}`}>{row.mapped.staffAnalysis.detailedDescription || '—'}</span>
                    </div>
                    <div className={styles.fieldItem}>
                      <span className={styles.fieldLabel}>Điều trị/y lệnh</span>
                      <span className={`${styles.fieldValue} ${styles.descText}`}>{row.mapped.staffAnalysis.treatmentOrders || '—'}</span>
                    </div>
                    <div className={styles.fieldItem}>
                      <span className={styles.fieldLabel}>Hành động khắc phục</span>
                      <span className={`${styles.fieldValue} ${styles.descText}`}>{row.mapped.staffAnalysis.correctiveActions || '—'}</span>
                    </div>
                    <div className={styles.fieldItem}>
                      <span className={styles.fieldLabel}>Đề xuất phòng ngừa</span>
                      <span className={`${styles.fieldValue} ${styles.descText}`}>{row.mapped.staffAnalysis.preventionRecommendations || '—'}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Warnings */}
              {isExpanded && row.warnings.length > 0 && (
                <div className={styles.rowWarnings}>
                  {row.warnings.map((w, i) => <div key={i} className={styles.warningItem}>⚠️ {w}</div>)}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className={styles.previewPager}>
          <button className={styles.pagerBtn} disabled={page === 0} onClick={() => setPage((p) => p - 1)}>‹</button>
          <span>Trang {page + 1} / {totalPages} ({filteredRows.length}{showOnlyErrors ? ' hàng lỗi' : ' bản ghi'})</span>
          <button className={styles.pagerBtn} disabled={page >= totalPages - 1} onClick={() => setPage((p) => p + 1)}>›</button>
        </div>
      )}

      {/* Bulk-apply confirm dialog */}
      {bulkConfirm && (
        <div className={styles.bulkConfirmOverlay}>
          <div className={styles.bulkConfirmBox}>
            <div className={styles.bulkConfirmIcon}>🏥</div>
            <p className={styles.bulkConfirmTitle}>Áp dụng cho nhiều hàng?</p>
            <p className={styles.bulkConfirmDesc}>
              Còn <strong>{bulkConfirm.affectedCount}</strong> hàng khác có cùng giá trị{' '}
              <strong>"{bulkConfirm.rawText}"</strong>.<br />
              Áp dụng <strong>{bulkConfirm.label}</strong> cho tất cả không?
            </p>
            <div className={styles.bulkConfirmActions}>
              <button className={styles.bulkBtnNo} onClick={handleBulkConfirmNo}>Không, chỉ hàng vừa chọn</button>
              <button className={styles.bulkBtnYes} onClick={handleBulkConfirmYes}>
                ✅ Áp dụng {bulkConfirm.affectedCount} hàng còn lại
              </button>
            </div>
          </div>
        </div>
      )}

      {unresolvedCount > 0 && (
        <div className={styles.unresolvedWarning}>
          ⚠️ Còn <strong>{unresolvedCount}</strong> hàng chưa chọn khoa phòng. Vui lòng chọn hoặc bỏ qua để tiếp tục.
        </div>
      )}

      <div className={styles.stepActions}>
        <Button variant="secondary" onClick={onBack}>‹ Quay lại</Button>
        <Button variant="primary" onClick={onNext}>
          Tiếp tục xác nhận ({rows.length} bản ghi) ›
        </Button>
      </div>
    </div>
  );
};


// ─── Step 3: Confirm & Import ─────────────────────────────────────────────────

interface Step3Props {
  rows: ImportRow[];
  progress: ImportProgress;
  onBack: () => void;
  onImport: () => void;
}

const Step3Confirm: React.FC<Step3Props> = ({ rows, progress, onBack, onImport }) => {
  const unresolvedCount = countUnresolved(rows);
  const readyCount      = rows.length - unresolvedCount;
  const skippedCount    = unresolvedCount;
  const duplicateSkipped = progress.duplicateSkipped;

  const pct = progress.total > 0 ? Math.round((progress.done / progress.total) * 100) : 0;

  return (
    <div className={styles.step3}>
      {!progress.running && !progress.finished && (
        <>
          <div className={styles.confirmSummary}>
            <div className={styles.confirmCard}>
              <div className={styles.confirmCardNum}>{rows.length}</div>
              <div className={styles.confirmCardLabel}>Tổng hàng</div>
            </div>
            <div className={`${styles.confirmCard} ${styles.confirmCardReady}`}>
              <div className={styles.confirmCardNum}>{readyCount}</div>
              <div className={styles.confirmCardLabel}>Sẵn sàng nhập</div>
            </div>
            {skippedCount > 0 && (
              <div className={`${styles.confirmCard} ${styles.confirmCardSkip}`}>
                <div className={styles.confirmCardNum}>{skippedCount}</div>
                <div className={styles.confirmCardLabel}>Bỏ qua (thiếu khoa)</div>
              </div>
            )}
            {duplicateSkipped > 0 && (
              <div className={`${styles.confirmCard} ${styles.confirmCardDuplicate}`}>
                <div className={styles.confirmCardNum}>{duplicateSkipped}</div>
                <div className={styles.confirmCardLabel}>Trùng lặp (bỏ qua)</div>
              </div>
            )}
          </div>

          <div className={styles.confirmNote}>
            <p>Tất cả bản ghi sẽ được tạo ở trạng thái <strong>Bản nháp</strong>.</p>
            <p>Sau khi nhập, bạn có thể mở từng bản ghi để kiểm tra và gửi báo cáo.</p>
            {skippedCount > 0 && (
              <p className={styles.confirmNoteWarn}>
                ⚠️ {skippedCount} hàng không có khoa phòng hợp lệ sẽ bị bỏ qua.
              </p>
            )}
            {duplicateSkipped > 0 && (
              <p className={styles.confirmNoteWarn}>
                🔁 {duplicateSkipped} hàng đã tồn tại trong hệ thống (trùng Mã MSSC) sẽ bị bỏ qua.
              </p>
            )}
          </div>

          <div className={styles.stepActions}>
            <Button variant="secondary" onClick={onBack} disabled={progress.running}>‹ Quay lại</Button>
            <Button variant="primary" onClick={onImport} disabled={readyCount === 0}>
              ✅ Nhập {readyCount} bản ghi vào hệ thống
            </Button>
          </div>
        </>
      )}

      {(progress.running || progress.finished) && (
        <div className={styles.progressSection}>
          <div className={styles.progressHeader}>
            {progress.finished
              ? `✅ Hoàn tất: ${progress.done - progress.errors.length} thành công, ${progress.errors.length} lỗi${progress.duplicateSkipped > 0 ? `, ${progress.duplicateSkipped} bỏ qua trùng lặp` : ''}`
              : `Đang nhập… ${progress.done}/${progress.total}`}
          </div>
          <div className={styles.progressBar}>
            <div className={styles.progressFill} style={{ width: `${pct}%` }} />
          </div>
          <div className={styles.progressPct}>{pct}%</div>

          {progress.errors.length > 0 && (
            <div className={styles.errorList}>
              <strong>Các lỗi xảy ra:</strong>
              {progress.errors.map((e, i) => <div key={i} className={styles.errorItem}>• {e}</div>)}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Main Modal
// ─────────────────────────────────────────────────────────────────────────────

export const ImportIncidentsModal: React.FC<Props> = ({ isOpen, onClose, onImportComplete }) => {
  const [step, setStep] = useState<Step>(1);

  // Multi-file slot state (danhsach required; phantich + danhgia optional)
  const [fileSlots, setFileSlots] = useState<Partial<Record<SlotKey, FileSlot>>>({});

  // Mapped + merged rows shown in Step 2
  const [importRows, setImportRows] = useState<ImportRow[]>([]);

  // Import progress
  const [progress, setProgress] = useState<ImportProgress>({
    total: 0, done: 0, errors: [], running: false, finished: false, duplicateSkipped: 0,
  });

  // Load all form options when modal mounts
  const {
    departmentOptions,
    patientGenderOptions,
    incidentSeverityOptions,
    incidentReportTypeOptions,
    incidentOccurrenceStatusOptions,
    incidentNotifyStatusOptions,
    loading: optionsLoading,
  } = useFormOptions('import-incidents');

  // Build a combined options object for Step2 rendering
  const formOptions: FullMapRowOptions = {
    departmentOptions,
    genderOptions:           patientGenderOptions ?? [],
    reportTypeOptions:       incidentReportTypeOptions ?? [],
    occurrenceStatusOptions: incidentOccurrenceStatusOptions ?? [],
    severityOptions:         incidentSeverityOptions ?? [],
    notifyStatusOptions:     incidentNotifyStatusOptions ?? [],
  };

  // Reset on close
  useEffect(() => {
    if (!isOpen) {
      const timer = setTimeout(() => {
        setStep(1);
        setFileSlots({});
        setImportRows([]);
        setProgress({ total: 0, done: 0, errors: [], running: false, finished: false, duplicateSkipped: 0 });
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  // Helper: build merged ImportRow[] from all slots
  const buildMergedRows = useCallback((slots: Partial<Record<SlotKey, FileSlot>>, deptOpts: typeof departmentOptions, genderOpts: typeof patientGenderOptions) => {
    const ds = slots.danhsach;
    if (!ds) return [];
    const mapOpts: MapRowOptions = { departmentOptions: deptOpts, genderOptions: genderOpts ?? [] };
    const danhsachRows = mapAllRows(ds.rawRows, 'danhsach', mapOpts);
    const phantichRows = slots.phantich ? mapAllRows(slots.phantich.rawRows, 'phantich', mapOpts) : [];
    const danhgiaRows  = slots.danhgia  ? mapAllRows(slots.danhgia.rawRows,  'danhgia',  mapOpts) : [];
    return mergeImportRows(danhsachRows, phantichRows, danhgiaRows);
  }, []);

  // Re-map rows when departmentOptions finish loading (0 → N), but only once per load.
  // Using a ref to avoid infinite loop from new array refs returned by useFormOptions every render.
  const deptLoadedRef = useRef(false);
  useEffect(() => {
    if (departmentOptions.length > 0 && !deptLoadedRef.current) {
      deptLoadedRef.current = true;
      if (fileSlots.danhsach) {
        const timer = setTimeout(() => {
          setImportRows(buildMergedRows(fileSlots, departmentOptions, patientGenderOptions));
        }, 0);
        return () => clearTimeout(timer);
      }
    }
    // Reset ref when options unload (modal close resets fileSlots anyway)
    if (departmentOptions.length === 0) {
      deptLoadedRef.current = false;
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [departmentOptions.length]);

  // ── Handle a new file dropped onto a slot ───────────────────────────────

  const handleSlotFile = useCallback(
    (slotKey: SlotKey, file: File, template: ImportTemplate, rawRows: Record<string, string>[]) => {
      setFileSlots((prev) => {
        const next = { ...prev, [slotKey]: { file, template, rawRows } };
        return next;
      });
    },
    [],
  );

  const handleSlotRemove = useCallback((slotKey: SlotKey) => {
    setFileSlots((prev) => {
      const next = { ...prev };
      delete next[slotKey];
      return next;
    });
  }, []);

  // ── Step 1 → Step 2 ─────────────────────────────────────────────────────

  const handleGoToStep2 = useCallback(() => {
    const merged = buildMergedRows(fileSlots, departmentOptions, patientGenderOptions);
    setImportRows(merged);
    setStep(2);
  }, [fileSlots, departmentOptions, patientGenderOptions, buildMergedRows]);

  // ── Resolve ambiguous department ─────────────────────────────────────────

  const handleResolve = useCallback((rowIndex: number, field: string, value: string, label: string) => {
    setImportRows((prev) =>
      prev.map((r) => {
        if (r.rowIndex !== rowIndex) return r;
        const newUnresolved = { ...r.unresolved };
        if (value) delete newUnresolved[field];
        const nameField = field === 'departmentId' ? 'departmentName' : 'reportingDepartmentName';
        return { ...r, unresolved: newUnresolved, mapped: { ...r.mapped, [field]: value, [nameField]: label } };
      }),
    );
  }, []);

  const handleResolveAll = useCallback((rawText: string, field: string, value: string, label: string) => {
    const nameField = field === 'departmentId' ? 'departmentName' : 'reportingDepartmentName';
    const rawKeys = field === 'departmentId'
      ? ['8. Khoa người bệnh điều trị', 'Khoa điều trị']
      : ['3. Khoa/phòng báo cáo', 'Khoa/phòng báo cáo'];
    setImportRows((prev) =>
      prev.map((r) => {
        if (!r.unresolved[field]) return r;
        const rowRawText = rawKeys.reduce((acc: string, k: string) => acc || r.raw[k] || '', '');
        if (rowRawText !== rawText) return r;
        const newUnresolved = { ...r.unresolved };
        if (value) delete newUnresolved[field];
        return { ...r, unresolved: newUnresolved, mapped: { ...r.mapped, [field]: value, [nameField]: label } };
      }),
    );
  }, []);

  // ── Import execution ─────────────────────────────────────────────────────

  const handleImport = useCallback(async () => {
    const readyRows = importRows.filter((r) => Object.keys(r.unresolved).length === 0);

    // ── Duplicate check via legacyId (MSSC) ──────────────────────────────
    const legacyIds = readyRows
      .map((r) => (r.mapped as Record<string, unknown>).legacyId as string | undefined)
      .filter((id): id is string => !!id);
    const existingSet = new Set(
      legacyIds.length > 0 ? await medicalIncidentService.checkLegacyIds(legacyIds) : [],
    );
    const rowsToImport = readyRows.filter(
      (r) => {
        const id = (r.mapped as Record<string, unknown>).legacyId as string | undefined;
        return !id || !existingSet.has(id);
      },
    );
    const duplicateSkipped = readyRows.length - rowsToImport.length;
    // ─────────────────────────────────────────────────────────────────────

    setProgress({ total: rowsToImport.length, done: 0, errors: [], running: true, finished: false, duplicateSkipped });

    const errors: string[] = [];
    let done = 0;

    for (const row of rowsToImport) {
      try {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await medicalIncidentService.create({ ...row.mapped, isImported: true } as any);
        done++;
      } catch (e) {
        errors.push(`Hàng ${row.rowIndex + 1}: ${String(e)}`);
        done++;
      }
      setProgress((p) => ({ ...p, done, errors: [...errors] }));
    }

    setProgress({ total: rowsToImport.length, done, errors, running: false, finished: true, duplicateSkipped });
    onImportComplete(done - errors.length);
  }, [importRows, onImportComplete]);

  const handleClose = () => {
    if (progress.running) return;
    onClose();
  };

  const getTitle = () => {
    if (step === 1) return 'Nhập sự cố từ file – Bước 1: Tải file';
    if (step === 2) return 'Nhập sự cố từ file – Bước 2: Xem trước dữ liệu';
    return 'Nhập sự cố từ file – Bước 3: Xác nhận';
  };

  // Primary file info for Step2 header
  const primaryFile = fileSlots.danhsach?.file ?? null;
  const primaryTemplate: ImportTemplate = fileSlots.danhsach?.template ?? 'danhsach';

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title={getTitle()}
      size="lg"
      closeOnOverlayClick={!progress.running}
    >
      <StepIndicator current={step} />

      {step === 1 && (
        <Step1FileUpload
          optionsLoading={optionsLoading}
          slots={fileSlots}
          onFile={handleSlotFile}
          onRemove={handleSlotRemove}
          onNext={handleGoToStep2}
        />
      )}

      {step === 2 && primaryFile && (
        <Step2MapPreview
          file={primaryFile}
          template={primaryTemplate}
          rows={importRows}
          departmentOptions={departmentOptions}
          formOptions={formOptions}
          onResolve={handleResolve}
          onResolveAll={handleResolveAll}
          onBack={() => setStep(1)}
          onNext={() => setStep(3)}
        />
      )}

      {step === 3 && (
        <Step3Confirm
          rows={importRows}
          progress={progress}
          onBack={() => setStep(2)}
          onImport={handleImport}
        />
      )}
    </Modal>
  );
};

