/**
 * SCYK browser URL segments (tiếng Việt, không dùng `medical-incidents`).
 * API BFF vẫn `/medical-incidents`, `/fall-location-warnings` — chỉ đổi route MFE.
 */

/** Danh sách sự cố */
export const SU_CO = 'su-co';

/** Báo cáo */
export const BC = 'bc';

/** Cảnh báo */
export const CANH_BAO = 'canh-bao';

export const scykRoutes = {
  /** Trang chủ / danh sách sự cố */
  home: SU_CO,
  incidentNew: `${SU_CO}/tao-moi`,
  incidentDetail: (id: string) => `${SU_CO}/${id}`,

  reportDaily: `${BC}/hang-ngay`,
  reportDailyNew: `${BC}/hang-ngay/tao-moi`,
  reportStats: `${BC}/thong-ke`,
  reportServiceMismatch: `${BC}/nham-dv`,
  reportFall: `${BC}/te-nga`,

  fallWarnings: `${CANH_BAO}/te-nga`,
  fallWarningNew: `${CANH_BAO}/te-nga/tao-moi`,
  fallWarningDetail: (id: string) => `${CANH_BAO}/te-nga/${id}`,
} as const;

export const SCYK_DEFAULT_ROUTE = scykRoutes.home;

/** Legacy Auth/menu paths → route segment (sau import CSV mới có thể bỏ). */
const LEGACY_MENU_TO_ROUTE: Record<string, string> = {
  '/medical-incidents': scykRoutes.home,
  '/fall-location-warnings': scykRoutes.fallWarnings,
  '/medical-incidents/daily-reports': scykRoutes.reportDaily,
  '/medical-incidents/reports': scykRoutes.reportStats,
  '/medical-incidents/reports/service-mismatch': scykRoutes.reportServiceMismatch,
  '/medical-incidents/reports/fall': scykRoutes.reportFall,
  [`/${SU_CO}`]: scykRoutes.home,
};

/** Chuẩn hóa path từ Auth menu hoặc defaultMenuUrl → segment `su-co/...`. */
export function normalizeMenuPathToRoute(menuPath: string | undefined): string {
  if (!menuPath || menuPath === '/') return SCYK_DEFAULT_ROUTE;
  const withoutPrefix = menuPath.replace(/^\/(m-inc|scyk)\/?/, '').replace(/^\//, '');
  const legacyKey = `/${withoutPrefix.split('/').filter(Boolean).join('/')}`;
  const legacyFull = menuPath.match(/^\/(m-inc|scyk)/)
    ? menuPath.replace(/^\/(m-inc|scyk)/, '') || '/'
    : `/${withoutPrefix}`;
  if (LEGACY_MENU_TO_ROUTE[legacyFull]) return LEGACY_MENU_TO_ROUTE[legacyFull];
  if (LEGACY_MENU_TO_ROUTE[`/${withoutPrefix}`]) return LEGACY_MENU_TO_ROUTE[`/${withoutPrefix}`];
  if (withoutPrefix.startsWith('medical-incidents')) {
    return withoutPrefix.replace(/^medical-incidents\/?/, SU_CO).replace(/^\/+/, '') || SU_CO;
  }
  if (withoutPrefix.startsWith('fall-location-warnings')) {
    return withoutPrefix.replace(/^fall-location-warnings\/?/, scykRoutes.fallWarnings).replace(/^\/+/, '');
  }
  return withoutPrefix.replace(/^\/+/, '');
}
